// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 blockNumber, uint256 warpTime) public {
        vm.assume(blockNumber > 0);
        vm.assume(warpTime > 0);
        vm.roll(blockNumber);
        vm.warp(warpTime);
        address sender = address(0x1337);
        vm.deal(sender, 10 ether);
        vm.prank(sender);
        (bool success,) = address(c).call{value: 10 ether}("");
        require(success, "call failed");

        bool isDivisible = (blockNumber % 15 == 0);
        bool balanceIsZero = (address(c).balance == 0);
        assertTrue(balanceIsZero == isDivisible);
    }
}
